&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Goule&lt;div style=&quot;float:right;&quot;&gt;FP 1&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Mort-vivant&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Mort-vivant.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Ruines-Donjons&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Ruines-Donjons.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Temp&#233;r&#233;&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Temp&#233;r&#233;.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire p.173&lt;/i&gt;, Codex monstrueux p.102
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;PX&lt;/b&gt; 400
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;Mort-vivant&lt;/a&gt; de taille M, CM
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Init&lt;/b&gt; +2 ; &lt;b&gt;Sens&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; 18 m (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +7
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;D&#233;fense&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;CA&lt;/b&gt; 14, contact 12, pris au d&#233;pourvu 12 (Dex +2, naturelle +2)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;pv&lt;/b&gt; 13 (2d8+4)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;R&#233;f&lt;/b&gt; +2, &lt;b&gt;Vig&lt;/b&gt; +2, &lt;b&gt;Vol&lt;/b&gt; +5
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Capacit&#233;s d&#233;fensives&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Canalisation-(Capacit&#233;).html&quot; title=&quot;r&#233;sistance &#224; la canalisation&quot;&gt;r&#233;sistance &#224; la canalisation&lt;/a&gt; +2 
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Attaque&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;VD&lt;/b&gt; 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +3 (1d6+1 et maladie et paralysie) et 2 griffes, +3 (1d6+1 et paralysie)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Paralysie-(Capacit&#233;).html&quot; title=&quot;Paralysie (Ext ou Sur)&quot;&gt;paralysie&lt;/a&gt; (1d4+1 rounds, DD 13, les elfes sont immunis&#233;s contre cet effet)
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Caract&#233;ristiques&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;For&lt;/b&gt; 13, &lt;b&gt;Dex&lt;/b&gt; 15, &lt;b&gt;Con&lt;/b&gt; -, &lt;b&gt;Int&lt;/b&gt; 13, &lt;b&gt;Sag&lt;/b&gt; 14, &lt;b&gt;Cha&lt;/b&gt; 14
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;BBA&lt;/b&gt; +1, &lt;b&gt;BMO&lt;/b&gt; +2, &lt;b&gt;DMD&lt;/b&gt; 14
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Dons&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Finesse.html&quot; title=&quot;Attaque en finesse&quot;&gt;Attaque en finesse&lt;/a&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Comp&#233;tences&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +4, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +7, &lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; +6, &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt; +3, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +7
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Langues&lt;/b&gt; commun
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;&#201;cologie&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Environnement&lt;/b&gt; terre ferme
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Organisation sociale&lt;/b&gt; solitaire, bande (2-4) ou meute (7-12)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Tr&#233;sor&lt;/b&gt; standard
&lt;/div&gt;
&lt;div class=&quot;BDsoustitre&quot;&gt;Capacit&#233;s sp&#233;ciales&lt;/div&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;FIEVREDESGOULES&quot; href=&quot;#FIEVREDESGOULES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Maladie : fi&#232;vre des goules (Sur).&lt;/b&gt; Morsure - blessure ; &lt;i&gt;JS&lt;/i&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 13 ; &lt;i&gt;incubation&lt;/i&gt; 1 jour ; &lt;i&gt;fr&#233;quence&lt;/i&gt; 1/jour  ; &lt;i&gt;effet&lt;/i&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissement temporaire&lt;/a&gt; 1d3 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Con&lt;/a&gt; et 1d3 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dex&lt;/a&gt; ; &lt;i&gt; gu&#233;rison&lt;/i&gt; 2 r&#233;ussites cons&#233;cutives. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; d&#233;pend du &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;. Lorsqu&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Humano&#239;de.html&quot; title=&quot;Humano&#239;de&quot;&gt;humano&#239;de&lt;/a&gt; meurt de la fi&#232;vre des goules, il se rel&#232;ve sous la forme d&#39;une goule d&#232;s que sonne minuit. Il ne conserve aucune des capacit&#233;s qu&#39;il poss&#233;dait de son vivant et n&#39;est pas soumis au contr&#244;le des autres goules, la chair des vivants l&#39;attire et il se comporte comme une goule normale. Ceux qui poss&#232;dent 4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; ou plus se rel&#232;vent sous la forme de &lt;a class=&quot;pagelink&quot; href=&quot;Bl&#234;me.html&quot; title=&quot;Bl&#234;me&quot;&gt;bl&#234;mes&lt;/a&gt;.
&lt;/div&gt;
&lt;/div&gt;&lt;br /&gt;
&lt;center&gt;&lt;img src=&quot;/wiki/public/upload/Bestiaire/Goule_img.jpg&quot; width=&quot;90%&quot; style=&quot;float: none; margin: 5px;&quot;/&gt;&lt;/center&gt;&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;div style=&quot;float:right; background-color: #fff; padding: 0 0 0 0; margin: 0 0 4px 8px&quot;&gt;
&lt;table CLASS=&quot;tablo autoalt&quot;&gt;&lt;caption&gt;Variantes de goule&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Nom&lt;/td&gt;&lt;td&gt;FP&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chauve-Souris-Aile-De-Suie.html&quot; title=&quot;Chauve-souris aile de suie&quot;&gt;Chauve-souris aile de suie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1/2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Molosse-Goule.html&quot; title=&quot;Molosse goule&quot;&gt;Molosse goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Goule.html&quot; title=&quot;Goule&quot;&gt;Goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Goule-Sournoise.html&quot; title=&quot;Goule sournoise&quot;&gt;Goule sournoise&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Goule-Traqueuse.html&quot; title=&quot;Goule traqueuse&quot;&gt;Goule traqueuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;6&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grand-Veneur-Goule.html&quot; title=&quot;Grand-veneur goule&quot;&gt;Grand-veneur goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;7&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Assassin-Masqu&#233;.html&quot; title=&quot;Assassin masqu&#233;&quot;&gt;Assassin masqu&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Commandant-Goule.html&quot; title=&quot;Commandant goule&quot;&gt;Commandant goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;8&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antique-Fossoyeur.html&quot; title=&quot;Antique fossoyeur&quot;&gt;Antique fossoyeur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monarque-Goule.html&quot; title=&quot;Monarque goule&quot;&gt;Monarque goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;12&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;i&gt;Cette cr&#233;ature humano&#239;de poss&#232;de de longues dents ac&#233;r&#233;es et sa peau p&#226;le semble avoir &#233;t&#233; &#233;tir&#233;e autour d’un corps affam&#233;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Les goules sont des morts-vivants qui hantent les cimeti&#232;res et d&#233;vorent les cadavres. Selon certaines l&#233;gendes, les premi&#232;res goules auraient &#233;t&#233; des humains cannibales revenus de la mort &#224; cause de leurs app&#233;tits contre nature. D’autres parlent plut&#244;t d’humains qui se seraient repus en d&#233;vorant les cadavres en putr&#233;faction de leurs fr&#232;res puis qui seraient
morts &#224; cause des terribles maladies qu’ils avaient ainsi contract&#233;es. Quoi qu’il en soit, la v&#233;ritable origine de ces charognards morts-vivants reste vague.&lt;br /&gt;&lt;br /&gt;Les goules se tapissent aux abords de la civilisation (dans ou pr&#232;s des cimeti&#232;res, ou dans les &#233;gouts des villes), l&#224; o&#249; elles peuvent mettre la main sur d’amples r&#233;serves de leur nourriture favorite. Elles pr&#233;f&#232;rent les corps en d&#233;composition et enterrent d’ailleurs souvent leurs victimes pendant un moment afin d’en am&#233;liorer le go&#251;t. Si la faim les y pousse, elles d&#233;vorent parfois des proies fra&#238;chement tu&#233;es. La plupart des goules de la surface vivent de mani&#232;re primitive mais certaines rumeurs parlent de cit&#233;s souterraines compos&#233;es de goules dirig&#233;es par des pr&#234;tres v&#233;n&#233;rant d’anciens dieux cruels ou d’&#233;tranges seigneurs-d&#233;mons de la faim.&lt;br /&gt;&lt;br /&gt;Les habitudes alimentaires de ces goules &#171; civilis&#233;es &#187; n’en sont pas pour autant moins horribles. En fait, l’id&#233;e d’une table bien dress&#233;e lors d’un banquet de goules est peut-&#234;tre m&#234;me plus terrifiante que celle d’un repas fra&#238;chement extrait de son cercueil.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Bl&#234;me&lt;a class=&quot;headeranchor&quot; id=&quot;Bl&#234;me_1&quot; href=&quot;#Bl&#234;me_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Bl&#234;me.html&quot; title=&quot;Bl&#234;me&quot;&gt;bl&#234;mes&lt;/a&gt; sont des goules qui poss&#232;dent l’arch&#233;type &#171; &#233;volu&#233; &#187;. La paralysie des bl&#234;mes affectent m&#234;me les elfes. Les bl&#234;mes se regroupent en meutes ou dirigent des bandes de goules normales. L’odeur de mort et de corruption qui &#233;mane de ces cr&#233;atures est si puissante qu’elles gagnent la capacit&#233; extraordinaire de &lt;a class=&quot;pagelink&quot; href=&quot;Puanteur-(Capacit&#233;).html&quot; title=&quot;Puanteur&quot;&gt;puanteur&lt;/a&gt; (rayon de 3 m, &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; DD 15 annule, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreux&lt;/a&gt; pendant 1d6+4 minutes).&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Lac&#233;don&lt;a class=&quot;headeranchor&quot; id=&quot;Lac&#233;don_2&quot; href=&quot;#Lac&#233;don_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ces cousins aquatiques des goules vivent pr&#232;s des r&#233;cifs cach&#233;s et des dangers qui menacent les navires. Les lac&#233;dons ont une vitesse de d&#233;placement de base de 9 m&#232;tres et une vitesse de nage de 9 m&#232;tres.
&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;&#201;cologie&lt;a class=&quot;headeranchor&quot; id=&quot;&#201;cologie_3&quot; href=&quot;#&#201;cologie_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float: right; margin-left: 10px; margin-right: 0px; max-width: 300px;&quot; class=&quot;presentation recentre&quot;&gt;
&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h4 class=&quot;separator&quot;&gt;La faim&lt;a class=&quot;headeranchor&quot; id=&quot;La_faim_0&quot; href=&quot;#La_faim_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;Les goules sont tenaill&#233;es par la faim mais elles n’ont pas besoin de se nourrir pour survivre : elles peuvent vivre des mill&#233;naires sans absorber une once de nourriture. Cependant, elles sont consum&#233;es par le besoin de manger de la chair.&lt;br /&gt;&lt;br /&gt;La silhouette de la goule refl&#232;te la quantit&#233; de chair qu’elle a engloutie, comme chez les humains. La plupart des goules sont maigres mais les sp&#233;cimens bien nourris sont gras. Le poids et le r&#233;gime alimentaire de la goule n’influent pas sur son app&#233;tit ni sa force, une goule bien nourrie &#233;prouvant la m&#234;me faim qu’une goule n’ayant pas mang&#233; depuis longtemps. Quelle que soit leur silhouette, toutes les goules sont fortes et agiles, leur puissance venant de la magie n&#233;cromantique qui anime leur corps.&lt;br /&gt;&lt;br /&gt;Les pr&#233;f&#233;rences gastronomiques varient fortement d’une goule &#224; l’autre, mais la plupart pr&#233;f&#232;rent les proies faisand&#233;es aux proies fra&#238;chement tu&#233;es. L’antre d’une goule est souvent dot&#233; de cachettes o&#249; la cr&#233;ature stocke les morceaux de choix pendant des jours ou des semaines pour am&#233;liorer leur go&#251;t. Quant &#224; savoir quel est le meilleur type de victime, c’est un d&#233;bat anim&#233; chez les goules : certaines pr&#233;f&#232;rent les victimes &#226;g&#233;es qui ont men&#233; une vie longue et bien remplie car elles disent que cela am&#233;liore la saveur de la chair, tandis que d’autres pr&#233;f&#232;rent des victimes plus jeunes et plus tendres. Les plus cruelles taillent un morceau dans une victime encore vivante et le d&#233;gustent sous ses yeux.&lt;br /&gt;&lt;br /&gt;Ce n’est qu’une fois que la goule a appris &#224; ma&#238;triser sa faim qu’elle peut gagner en puissance et devenir plus qu’une b&#234;te affam&#233;e. Le processus varie d’un individu &#224; l’autre. Pour certaines, la force de caract&#232;re suffit, d’autres mangent r&#233;guli&#232;rement pour apaiser un peu leur faim et d’autres transforment leur app&#233;tit en d&#233;votion &#224; un dieu ou se mettent en qu&#234;te de grands pouvoirs magiques.&lt;br /&gt;&lt;br /&gt;&lt;/div&gt;Si les gens &#233;vitent de se rendre dans un cimeti&#232;re de nuit, c’est par peur des goules. Ces cr&#233;atures sont intelligentes, mais elles &#233;coutent rarement ce que les vivants ont &#224; dire et les traitent plus volontiers comme des repas que comme des amis. Les goules occupent une bonne place dans les contes superstitieux et sont afflig&#233;es d’une faim l&#233;gendaire. Les histoires de cannibales devenus des morts-vivants affam&#233;s dissuadent bien des gens de manger leurs morts, m&#234;me dans les situations les plus d&#233;sesp&#233;r&#233;es.&lt;br /&gt;&lt;br /&gt;Les goules sont toujours en qu&#234;te de chair humano&#239;de et leur soci&#233;t&#233; se d&#233;veloppe l&#224; o&#249; elles trouvent de fortes concentrations de vivants. Elles &#233;tendent progressivement leur domaine, au fur et &#224; mesure qu’elles contaminent de nouvelles victimes avec la fi&#232;vre des goules. Cette expansion peut se faire progressivement ou abruptement, mais ne s’arr&#234;te pas tant que quelqu’un n’a pas d&#233;busqu&#233; et &#233;limin&#233; toutes les goules. Les victimes potentielles ont de bonnes raisons de redouter les goules car la fi&#232;vre qu’elles transmettent entra&#238;ne une mort horrifiante. Une fois la maladie d&#233;clar&#233;e, la victime est tenaill&#233;e par une faim insatiable alors m&#234;me que son corps se met &#224; rejeter la nourriture et les boissons normales. Si le malade ne trouve rien &#224; manger, il devient de plus en plus violent car sa faim continue de grandir. On peut le soulager temporairement en lui donnant la chair d’un mort mais cela ne ralentit pas l’&#233;volution de la maladie. Le corps de la victime finit par succomber, cependant la victime d&#233;c&#233;d&#233;e se rel&#232;ve au premier coup de minuit, avide de chair fra&#238;che.&lt;br /&gt;&lt;br /&gt;La plupart des goules &#233;prouvent un tel m&#233;pris vis-&#224;-vis d’elles-m&#234;mes qu’elles ne ressentent aucune affection pour leurs semblables. Elles ont naturellement tendance &#224; se regrouper en meute pour chasser et se prot&#233;ger mutuellement, mais les membres d’une meute n’&#233;prouvent ni confiance ni amour les uns pour les autres. Une goule peut suivre loyalement un m&#234;me chef pendant des ann&#233;es et le trahir soudain si cela lui assure des repas plus fr&#233;quents. De base, les bl&#234;mes sont plus puissantes que les autres goules mais elles endossent rarement un r&#244;le de chef car elles se laissent emporter par leur agressivit&#233;. Cependant, quand une bl&#234;me appara&#238;t, il arrive que les goules se sentent plus courageuses gr&#226;ce &#224; elle et attaquent des communaut&#233;s elfiques qu’elles auraient &#233;vit&#233;es en son absence car trop dangereuses. &lt;br /&gt;&lt;br /&gt;Les cimeti&#232;res attirent naturellement les goules qui passent souvent leur existence en ces lieux. De petites meutes vivent souvent dans des terriers creus&#233;s sous un cimeti&#232;re o&#249; elles peuvent exhumer des cadavres pour satisfaire leur besoin de chair. Dans un cimeti&#232;re, des tombes curieusement pench&#233;es et des trous indiquent &#224; coup s&#251;r la pr&#233;sence d’une meute de goules. Certaines se contentent de cadavres pendant un temps mais toutes finissent par chasser les vivants.&lt;br /&gt;&lt;br /&gt;Les goules ne vivent pas toutes dans de sombres terriers sous les cimeti&#232;res. Dans certaines r&#233;gions isol&#233;es, elles disposent de villes voire de nations enti&#232;res peupl&#233;es de leurs semblables et de morts-vivants. Dans ces cit&#233;s, elles traitent les vivants comme du b&#233;tail. Les nations mortes-vivantes sont g&#233;n&#233;ralement dirig&#233;es par des liches ou des morts-vivants encore plus puissants mais, en certains lieux, les goules occupent des postes influents et il leur arrive m&#234;me de r&#233;gner. Les souverains de ces nations admettent qu’ils n’ont aucune chance de remporter une guerre contre les pays de vivants, bien plus peupl&#233;s, et concluent des accords avec leurs voisins pour n&#233;gocier des esclaves ou juste des cadavres. Les plus grands pays de morts-vivants utilisent les humains comme esclaves qui travaillent dans les fermes pour produire leur propre nourriture avant de terminer &#224; leur tour dans l’assiette de leurs ma&#238;tres.&lt;br /&gt;&lt;br /&gt;Les lac&#233;dons sont des goules aquatiques qui vivent dans des r&#233;cifs isol&#233;s et des cavernes sous-marines pr&#232;s des communaut&#233;s
humano&#239;des aquatiques comme celles des &lt;a class=&quot;pagelink&quot; href=&quot;Grindylow.html&quot; title=&quot;Grindylow&quot;&gt;grindylows&lt;/a&gt;, des &lt;a class=&quot;pagelink&quot; href=&quot;Locathah.html&quot; title=&quot;Locathah&quot;&gt;locathahs&lt;/a&gt; ou des &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Poisson-(Race).html&quot; title=&quot;Les hommes-poissons&quot;&gt;hommes-poissons&lt;/a&gt;. Dans les contes de ces habitants des mers, les lac&#233;dons sont aussi c&#233;l&#232;bres que les goules le sont dans les histoires des races de la terre ferme. &lt;br /&gt;&lt;br /&gt;Les lac&#233;dons qui pr&#233;f&#232;rent des proies faciles r&#233;sident pr&#232;s des c&#244;tes ou des routes commerciales tr&#232;s fr&#233;quent&#233;es o&#249; ils endurent de longues p&#233;riodes de disette jusqu’&#224; ce qu’un naufrage leur offre un glorieux festin sanglant. Les lac&#233;dons sont plus mobiles que les autres goules : s’ils d&#233;tectent le go&#251;t du sang humano&#239;de dans l’eau, ils peuvent remonter le courant qui leur a amen&#233; le sang sur des kilom&#232;tres, jusqu’&#224; trouver la source.&lt;br /&gt;&lt;br /&gt;&lt;div style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Codex monstrueux/Monster Codex&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMC.gif&quot; style=&quot;opacity: 0.7&quot; /&gt;
&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Nouvelles r&#232;gles raciales&lt;a class=&quot;headeranchor&quot; id=&quot;Nouvelles_r&#232;gles_raciales_7&quot; href=&quot;#Nouvelles_r&#232;gles_raciales_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Cette section pr&#233;sente un lignage d’ensorceleur ainsi que des dons et des sorts tr&#232;s appr&#233;ci&#233;s des goules.
&lt;h3 class=&quot;separator&quot;&gt;Dons&lt;a class=&quot;headeranchor&quot; id=&quot;Dons_4&quot; href=&quot;#Dons_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici quelques dons offrant de nouvelles perspectives aux goules.
&lt;center&gt;
&lt;table CLASS=&quot;tablo autoalt toutgauche filtrable&quot; WIDTH=&quot;100%&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Src&lt;/td&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;37%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cadavre-De-Compagnie.html&quot; title=&quot;Cadavre de compagnie&quot;&gt;Cadavre de compagnie&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Chasseur.html#COMPAGNONANIMAL&quot; title=&quot;Le chasseur&quot;&gt;compagnon animal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Goule.html&quot; title=&quot;Goule&quot;&gt;goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain d&#39;un compagnon animal mort-vivant&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Creuseur-De-Terrier.html&quot; title=&quot;Creuseur de terrier&quot;&gt;Creuseur de terrier&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Goule.html&quot; title=&quot;Goule&quot;&gt;Goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain d&#39;une vitesse de creusement&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Dormeur.html&quot; title=&quot;Dormeur&quot;&gt;Dormeur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Creuseur-De-Terrier.html&quot; title=&quot;Creuseur de terrier&quot;&gt;Creuseur de terrier&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Goule.html&quot; title=&quot;Goule&quot;&gt;goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain du pouvoir gu&#233;rison acc&#233;l&#233;r&#233;e pr&#232;s de terre ou de pierre&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Vieux-Comme-La-Poussi&#232;re.html&quot; title=&quot;Vieux comme la poussi&#232;re&quot;&gt;Vieux comme la poussi&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dormeur.html&quot; title=&quot;Dormeur&quot;&gt;Dormeur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Creuseur-De-Terrier.html&quot; title=&quot;Creuseur de terrier&quot;&gt;Creuseur de terrier&lt;/a&gt;, avoir &#233;t&#233; une &lt;a class=&quot;pagelink&quot; href=&quot;Goule.html&quot; title=&quot;Goule&quot;&gt;goule&lt;/a&gt; pendant au moins 500 ans&lt;/td&gt;&lt;td&gt;Emp&#234;che de mourir sauf si le corps est compl&#232;tement d&#233;truit&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sac-Dos.html&quot; title=&quot;Sac d&amp;#39;os&quot;&gt;Sac d&#39;os&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Goule.html&quot; title=&quot;Goule&quot;&gt;Goule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Bonus aux jets tests d&#39;&#201;vasion. Consid&#233;r&#233; comme d&#39;une taille inf&#233;rieure pour se faufiler&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/center&gt;
&lt;div class=&quot;row ligne&quot; style=&quot;&quot;&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Lignages d&#39;ensorceleur&lt;a class=&quot;headeranchor&quot; id=&quot;Lignages_densorceleur_5&quot; href=&quot;#Lignages_densorceleur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Il arrive qu’une personne contracte la fi&#232;vre des goules et survive. Si elle compte un ensorceleur parmi ses descendants, il h&#233;rite souvent de ce lignage.
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Goule.html&quot; title=&quot;Lignage Goule&quot;&gt;Goule&lt;/a&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;div class=&quot;col col-6 &quot; style=&quot;&quot;&gt;
&lt;h3 class=&quot;separator&quot;&gt;Sorts&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_6&quot; href=&quot;#Sorts_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les sorts des goules refl&#232;tent leur obsession pour la mort et leur faim constante.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Apparence-Charnue.html&quot; title=&quot;Apparence charnue&quot;&gt;Apparence charnue&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(CM)&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Alch 2&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;Apal 2&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;Inq 2&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ens&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;Mag 2&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html&quot; title=&quot;Le psychiste&quot;&gt;Psy 2&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;Sor 2&lt;/a&gt;). Une cr&#233;ature mort-vivante tangible para&#238;t vivante.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Terre-Affam&#233;e.html&quot; title=&quot;Terre affam&#233;e&quot;&gt;Terre affam&#233;e&lt;/a&gt;&lt;/i&gt;&lt;/b&gt; &lt;i&gt;(CM)&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;Dru 5&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ens&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;Mag 5&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;Sor 5&lt;/a&gt;). Envo&#251;te le sol pour qu&#39;il tire les cr&#233;atures sous la surface.&lt;br /&gt;&lt;/div&gt;&lt;/div&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
